// SleepNoise paint generator: the short, high-pigment ribbon strokes of the
// in-house pictorial language ("Pigmento") rendered as PNG pieces at build
// time. Own work generated by code: no image is downloaded, embedded or traced
// from anywhere, and no concrete artwork is referenced.
//
// Sources of truth: docs/design/color/lenguaje-pictorico.md (palette per
// texture, the ribbon stroke, the impasto rule) and
// docs/design/color/camino-contenido.html, whose JavaScript is the reference
// generator this file ports: same linear congruential generator, same order
// of random draws, same motifs and the same seed per house mix, so a piece can
// be reproduced and compared with the mock-up.
//
// The brush itself (generator, palette, ribbon, canvas) is the app's own
// SleepNoise/Design/Paint/Pigment.swift, compiled next to this file by
// generate.sh. Run it from anywhere inside the checkout:
//
//   scripts/paint/generate.sh            the four house-mix bands (2x and 3x) into the asset catalog
//   scripts/paint/generate.sh --proof    also real-size proofs of the bands in .build/shots/paint-*.png
//   scripts/paint/generate.sh --store    also one full-page piece per mix (1320 x 2868) in .build/paint-store/
//
// No dependencies beyond the macOS SDK that ships with Xcode.
// Notes, seeds and what is still open: scripts/paint/README.md.

import CoreGraphics
import Foundation
import ImageIO

// MARK: - The shared brush

// The generator, the palette, the ribbon and the canvas live in
// SleepNoise/Design/Paint/Pigment.swift, compiled next to this file by
// generate.sh: the app paints its window with the very same code, so a seed
// draws the same strokes here and on the page.

typealias LCG = Pigment.LCG
typealias Tint = Pigment.Tint
typealias Palette = Pigment.Palette
typealias Canvas = Pigment.Canvas
typealias P = Pigment.P

let black = Pigment.black
let sRGB = Pigment.sRGB

func fail(_ message: String) -> Never {
    FileHandle.standardError.write(Data("paint: \(message)\n".utf8))
    exit(1)
}

func canvas(width: Double, height: Double, scale: Double, focus: Double? = nil) -> Canvas {
    guard let cv = Canvas(width: width, height: height, scale: scale, focus: focus) else {
        fail("could not create a \(Int(width * scale))x\(Int(height * scale)) bitmap")
    }
    return cv
}

func ribbon(_ cv: Canvas, _ pts: [P], _ w: Double, _ light: Tint, _ base: Tint, _ alpha: Double, taper: Bool = false) {
    Pigment.ribbon(cv.context, pts, w, light, base, alpha, taper: taper)
}

func grain(_ cv: Canvas, _ R: inout LCG, _ alpha: Double) {
    Pigment.grain(cv.context, width: cv.width, height: cv.height, &R, alpha)
}

func strokeNoise(_ x0: Double, _ y0: Double, _ ang: Double, _ len: Double, _ steps: Int, _ R: inout LCG, _ dev: Double) -> [P] {
    Pigment.strokeNoise(x0, y0, ang, len, steps, &R, dev)
}

func strokeFlow(_ x0: Double, _ y0: Double, _ len: Double, _ steps: Int, _ field: (Double, Double) -> Double,
                _ scale: Double, _ drift: Double) -> [P] {
    Pigment.strokeFlow(x0, y0, len, steps, field, scale, drift)
}

func pick(_ R: inout LCG, _ c: [Tint], _ weights: [Double]) -> Int {
    Pigment.pick(&R, weights)
}

func times(_ n: Double, _ body: () -> Void) {
    Pigment.times(n, body)
}

// MARK: - Motifs (one per texture, abstract before figurative)

/// Tongues that rise and narrow, a core of light flame in the central 40 %
/// of the width, ember red at the edges, burnt wood outside; 30 % of the
/// tongues are black; half a dozen embers above.
func tongues(_ cv: Canvas, _ R: inout LCG, _ c: [Tint], density: Double) {
    let W = cv.width, H = cv.focus, cx = W / 2
    times(W * H / density) {
        let x0 = R.next() * W, y0 = H * 0.5 + R.next() * H * 0.55
        let d = abs(x0 - cx) / (W * 0.5)
        let len = (26 + R.next() * 44) * (d < 0.4 ? 1 : 0.7)
        let ang = -Double.pi / 2 + (R.next() - 0.5) * 0.5
        let p = strokeNoise(x0, y0, ang, len, 7, &R, 0.45)
        if R.next() < 0.30 {
            ribbon(cv, p, 6 + R.next() * 6, black, black, 0.85, taper: true)
            return
        }
        let k: Int
        if d < 0.4 { k = R.next() < 0.55 ? 1 : 0 } else if d < 0.7 { k = R.next() < 0.6 ? 2 : 1 } else { k = R.next() < 0.7 ? 3 : 2 }
        ribbon(cv, p, 8 + R.next() * 6, c[max(0, k - 1)], c[k], 0.92, taper: true)
    }
    for _ in 0..<6 {
        let x = cx + (R.next() - 0.5) * W * 0.5, y = H * 0.08 + R.next() * H * 0.42
        cv.context.setFillColor(c[R.next() < 0.5 ? 0 : 1].cgColor(alpha: 0.9))
        let w = 2 + R.next(), h = 2 + R.next()
        cv.context.fill(CGRect(x: x, y: y, width: w, height: h))
    }
}

enum Motif {
    static func white(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        times(W * H / 32) {
            let x = R.next() * W, y = R.next() * H, ang = R.next() * 6.28, len = 6 + R.next() * 4
            let p = strokeNoise(x, y, ang, len, 3, &R, 0.4)
            let k = pick(&R, c, [1, 4, 6])
            ribbon(cv, p, 3 + R.next(), c[max(0, k - 1)], c[k], 0.85)
        }
    }

    static func pink(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        times(W * H / 70) {
            let x = R.next() * W, y = R.next() * H, ang = (R.next() - 0.5) * 0.7, len = 10 + R.next() * 8
            let p = strokeNoise(x, y, ang, len, 4, &R, 0.5)
            let k = pick(&R, c, [1, 3, 5, 5])
            ribbon(cv, p, 4 + R.next() * 2, c[max(0, k - 1)], c[k], 0.9)
        }
    }

    static func brown(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        times(W * H / 160) {
            let x = R.next() * W - 10, y = R.next() * H, ang = (R.next() - 0.5) * 0.5, len = 22 + R.next() * 18
            let p = strokeNoise(x, y, ang, len, 6, &R, 0.3)
            let k = pick(&R, c, [1, 3, 5, 4])
            ribbon(cv, p, 7 + R.next() * 3, c[max(0, k - 1)], c[k], 0.9)
        }
    }

    static func rain(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height, ang = 72 * Double.pi / 180
        times(W * H / 55) {
            let x = R.next() * (W + 40) - 20, y = R.next() * (H + 40) - 20, a = ang + (R.next() - 0.5) * 0.2, len = 18 + R.next() * 16
            let p = strokeNoise(x, y, a, len, 6, &R, 0.25)
            let k = pick(&R, c, [1, 3, 5, 6])
            ribbon(cv, p, 2 + R.next(), c[max(0, k - 1)], c[k], 0.85)
        }
    }

    static func fan(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height, cx = W * 1.25, cy = H * 1.2
        times(W * H / 60) {
            let r = 40 + R.next() * (W * 1.3), a0 = Double.pi + R.next() * Double.pi * 0.6, da = (24 + R.next() * 24) / r
            var pts: [P] = []
            for s in 0...8 {
                let a = a0 + da * Double(s) / 8 + (R.next() - 0.5) * 0.015
                pts.append(P(x: cx + cos(a) * r, y: cy + sin(a) * r))
            }
            let k = pick(&R, c, [1, 3, 5, 6])
            ribbon(cv, pts, 3 + R.next() * 2, c[max(0, k - 1)], c[k], 0.85)
        }
    }

    static func ocean(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        let f = Pigment.ValueNoise(&R), g = Pigment.ValueNoise(&R)
        let field: (Double, Double) -> Double = { x, y in f(x, y) + 0.5 * g(x * 2, y * 2) }
        times(W * H / 48) {
            let x = R.next() * W, y = R.next() * H, len = 18 + R.next() * 18
            let p = strokeFlow(x, y, len, 8, field, 70, 0.12)
            let k = pick(&R, c, [1, 3, 6, 5])
            ribbon(cv, p, 5 + R.next() * 3, c[max(0, k - 1)], c[k], 0.9)
        }
    }

    static func thunder(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        times(W * H / 110) {
            let x = R.next() * W - 10, y = R.next() * H, ang = (R.next() - 0.5) * 0.3, len = 16 + R.next() * 14
            let p = strokeNoise(x, y, ang, len, 5, &R, 0.3)
            let k = pick(&R, c, [0, 1, 4, 9])
            ribbon(cv, p, 5 + R.next() * 2, c[max(0, k - 1)], c[k], 0.9)
        }
        // One crack, fixed by the seed, five bends.
        var x = W * 0.35 + R.next() * W * 0.3, y = -4.0
        var pts = [P(x: x, y: y)]
        for _ in 0..<5 {
            x += (R.next() - 0.5) * 34
            y += H * 0.22 + R.next() * 10
            pts.append(P(x: x, y: y))
        }
        ribbon(cv, pts, 3.5, c[0], c[1], 0.95)
    }

    static func campfire(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        cv.fill(c[3], alpha: 0.5)
        tongues(cv, &R, c, density: 90)
    }

    static func stream(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        cv.fill(c[3], alpha: 0.7)
        times(W * H / 120) {
            let y0 = R.next() * H, x0 = R.next() * W - 40, len = 40 + R.next() * 50, ph = R.next() * 6.28, amp = 3 + R.next() * 5
            var pts: [P] = []
            for s in 0...10 {
                pts.append(P(x: x0 + len * Double(s) / 10, y: y0 + sin(ph + Double(s) * 1.9) * amp))
            }
            let k = pick(&R, c, [1, 3, 5, 3])
            ribbon(cv, pts, 3 + R.next() * 2, c[max(0, k - 1)], c[k], 0.9)
        }
    }

    static func wind(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        cv.fill(c[3], alpha: 0.55)
        times(W * H / 70) {
            let x = R.next() * W - 60, y = R.next() * H, ang = (R.next() - 0.5) * 0.35, len = 60 + R.next() * 80
            let p = strokeNoise(x, y, ang, len, 10, &R, 0.12)
            let k = pick(&R, c, [1, 4, 5, 3])
            ribbon(cv, p, 1.5 + R.next(), c[max(0, k - 1)], c[k], 0.8)
        }
    }

    static func cabin(_ cv: Canvas, _ R: inout LCG, _ c: [Tint]) {
        let W = cv.width, H = cv.height
        cv.fill(c[3], alpha: 0.8)
        times(W * H / 220) {
            let x = R.next() * W - 80, y = R.next() * H, len = 80 + R.next() * 120
            let p = strokeNoise(x, y, 0, len, 8, &R, 0.05)
            let k = pick(&R, c, [1, 3, 6, 4])
            ribbon(cv, p, 6 + R.next() * 6, c[max(0, k - 1)], c[k], 0.85)
        }
        grain(cv, &R, 0.12)
    }
}

// MARK: - The four house mixes (inherit by dominant layer)

/// One house mix: its id in the app (`HouseMix.rawValue`), the seed of the
/// mock-up, the base palette and the composition of its layers.
struct HousePiece {
    let id: String
    let seed: UInt32
    let base: [Tint]
    let compose: (Canvas, inout LCG) -> Void
}

let housePieces: [HousePiece] = [
    // Rain over the pink field.
    HousePiece(id: "pinkAndRain", seed: 2101, base: Palette.pink) { cv, R in
        Motif.pink(cv, &R, Palette.pink)
        let c = Palette.rain, ang = 72 * Double.pi / 180, W = cv.width, H = cv.height
        times(W * H / 90) {
            let x = R.next() * (W + 40) - 20, y = R.next() * (H + 40) - 20, a = ang + (R.next() - 0.5) * 0.2, len = 18 + R.next() * 16
            let p = strokeNoise(x, y, a, len, 6, &R, 0.25)
            let k = pick(&R, c, [1, 3, 5, 4])
            ribbon(cv, p, 2 + R.next(), c[max(0, k - 1)], c[k], 0.8)
        }
    },
    // No warm pigment over the ocean: only the two dark olive tints of the wind, at 70 %.
    HousePiece(id: "seaAndWind", seed: 2102, base: Palette.ocean) { cv, R in
        Motif.ocean(cv, &R, Palette.ocean)
        let c = Palette.wind, W = cv.width, H = cv.height
        times(W * H / 240) {
            let x = R.next() * W - 60, y = R.next() * H, ang = (R.next() - 0.5) * 0.3, len = 60 + R.next() * 80
            let p = strokeNoise(x, y, ang, len, 10, &R, 0.12)
            ribbon(cv, p, 1.5 + R.next(), c[2], c[3], 0.7)
        }
    },
    // The tongues over the brown field.
    HousePiece(id: "brownAndFire", seed: 2103, base: Palette.brown) { cv, R in
        Motif.brown(cv, &R, Palette.brown)
        tongues(cv, &R, Palette.campfire, density: 110)
    },
    // The brown field alone.
    HousePiece(id: "wall", seed: 2104, base: Palette.brown) { cv, R in
        Motif.brown(cv, &R, Palette.brown)
    },
]

/// A piece as the mock-up paints it: the base tint pulled 45 % towards black,
/// a 6 % grain, then the composition. Same seed, same drawing at any size;
/// only the number of strokes follows the area.
func paint(_ piece: HousePiece, width: Double, height: Double, scale: Double, focus: Double? = nil) -> CGImage {
    let cv = canvas(width: width, height: height, scale: scale, focus: focus)
    var R = LCG(seed: piece.seed)
    cv.fill(piece.base[piece.base.count - 1].towardsBlack(0.45))
    grain(cv, &R, 0.06)
    piece.compose(cv, &R)
    guard let image = cv.image() else { fail("could not read the bitmap back") }
    return image
}

// MARK: - Output

func writePNG(_ image: CGImage, to url: URL) {
    try? FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
    guard let destination = CGImageDestinationCreateWithURL(url as CFURL, "public.png" as CFString, 1, nil)
    else { fail("could not open \(url.path) for writing") }
    CGImageDestinationAddImage(destination, image, nil)
    guard CGImageDestinationFinalize(destination) else { fail("could not write \(url.path)") }
}

/// The band of the Mixes sheet: 64 pt wide, bled off the left edge. The house
/// rows measure 72 pt at the Large text size (one line of recipe, measured in
/// the code, `Grid.rowSubtitle`, and in a capture of the sheet in both
/// languages), 80 from xL, 92 with a recipe of two lines and about 260 at
/// the largest accessibility size. The band is painted 288 pt tall so every
/// row shows it at 1:1, clipped from the top, and the edge of a ribbon is
/// never scaled soft. The composition is placed in the top 92 pt
/// (`bandFocus`, the band of the mock-up): the field goes on below it, the
/// tongues of the campfire do not move down with the extra height.
let bandWidth = 64.0
let bandHeight = 288.0
let bandFocus = 92.0
let rowHeight = 72.0
let bandScales = [2.0, 3.0]
let assetFolder = "SleepNoise/Resources/Assets.xcassets/Paint"

func imagesetJSON(id: String) -> String {
    """
    {
      "images" : [
        {
          "filename" : "HouseMix-\(id)@2x.png",
          "idiom" : "universal",
          "scale" : "2x"
        },
        {
          "filename" : "HouseMix-\(id)@3x.png",
          "idiom" : "universal",
          "scale" : "3x"
        }
      ],
      "info" : {
        "author" : "xcode",
        "version" : 1
      }
    }

    """
}

let folderJSON = """
{
  "info" : {
    "author" : "xcode",
    "version" : 1
  },
  "properties" : {
    "provides-namespace" : true
  }
}

"""

func writeAssets(root: URL) {
    let folder = root.appendingPathComponent(assetFolder)
    try? FileManager.default.createDirectory(at: folder, withIntermediateDirectories: true)
    try! folderJSON.write(to: folder.appendingPathComponent("Contents.json"), atomically: true, encoding: .utf8)
    var total = 0
    for piece in housePieces {
        let set = folder.appendingPathComponent("HouseMix-\(piece.id).imageset")
        try? FileManager.default.createDirectory(at: set, withIntermediateDirectories: true)
        try! imagesetJSON(id: piece.id).write(to: set.appendingPathComponent("Contents.json"), atomically: true, encoding: .utf8)
        for scale in bandScales {
            let url = set.appendingPathComponent("HouseMix-\(piece.id)@\(Int(scale))x.png")
            writePNG(paint(piece, width: bandWidth, height: bandHeight, scale: scale, focus: bandFocus), to: url)
            let bytes = (try? FileManager.default.attributesOfItem(atPath: url.path)[.size] as? Int) ?? 0
            total += bytes
            print("paint: \(assetFolder)/HouseMix-\(piece.id).imageset/\(url.lastPathComponent) · \(Int(bandWidth * scale))x\(Int(bandHeight * scale)) px · \(bytes) bytes")
        }
    }
    print("paint: \(housePieces.count) imagesets · \(total) bytes in the bundle")
}

/// Full-page pieces for the store capture: 1320 x 2868 px (440 x 956 pt at
/// 3x), never in the app bundle. The strokes are sized in points of the
/// mock-up, so a page painted at 1:1 turns the tongues into a field of thin
/// blades and the brown ribbons into gravel. The page is therefore painted
/// `storeZoom` times closer: fewer and larger strokes, the same gesture the
/// band shows at arm's length.
let storeZoom = 2.5
let storeSize = (width: 440.0, height: 956.0)

func writeStore(root: URL) {
    let folder = root.appendingPathComponent(".build/paint-store")
    for piece in housePieces {
        let url = folder.appendingPathComponent("HouseMix-\(piece.id).png")
        let image = paint(piece, width: storeSize.width / storeZoom, height: storeSize.height / storeZoom, scale: 3 * storeZoom)
        writePNG(image, to: url)
        print("paint: \(url.path.dropFirst(root.path.count + 1)) · \(image.width)x\(image.height) px")
    }
}

/// Proofs at real size (3x): the four bands on the sheet colour `hoja` and on
/// black under the 12 % veil of the Mixes row, with the gap of a 20 pt margin
/// between them, and the same at 2x. Two rows: the whole band (288 pt), and
/// the band clipped to the 72 pt row the sheet shows at Large. Nothing else,
/// so the paint is judged alone.
func writeProofs(root: URL) {
    let shots = root.appendingPathComponent(".build/shots")
    struct Ground { let name: String; let tint: Tint; let veil: Double }
    let grounds = [Ground(name: "hoja", tint: Tint(hex: 0x1C1C1E), veil: 0),
                   Ground(name: "negro-velo", tint: black, veil: 0.12)]
    for scale in bandScales {
        for ground in grounds {
            let gap = 20.0, margin = 24.0
            let width = margin * 2 + bandWidth * Double(housePieces.count) + gap * Double(housePieces.count - 1)
            let height = margin * 3 + bandHeight + rowHeight
            let w = Int(width * scale), h = Int(height * scale)
            guard let ctx = CGContext(data: nil, width: w, height: h, bitsPerComponent: 8, bytesPerRow: w * 4,
                                      space: sRGB, bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue)
            else { fail("could not create the proof bitmap") }
            ctx.scaleBy(x: CGFloat(scale), y: CGFloat(scale))
            ctx.setFillColor(ground.tint.cgColor())
            ctx.fill(CGRect(x: 0, y: 0, width: width, height: height))
            for (index, piece) in housePieces.enumerated() {
                let x = margin + Double(index) * (bandWidth + gap)
                let band = paint(piece, width: bandWidth, height: bandHeight, scale: scale, focus: bandFocus)
                // CGContext draws with the origin at the bottom: the clipped row
                // keeps the top of the band, as the sheet does.
                let whole = CGRect(x: x, y: height - margin - bandHeight, width: bandWidth, height: bandHeight)
                let row = CGRect(x: x, y: margin, width: bandWidth, height: rowHeight)
                let image = CGRect(x: x, y: margin + rowHeight - bandHeight, width: bandWidth, height: bandHeight)
                ctx.draw(band, in: whole)
                ctx.saveGState()
                ctx.clip(to: row)
                ctx.draw(band, in: image)
                ctx.restoreGState()
                if ground.veil > 0 {
                    ctx.setFillColor(black.cgColor(alpha: ground.veil))
                    ctx.fill([whole, row])
                }
            }
            let url = shots.appendingPathComponent("paint-bands-\(ground.name)@\(Int(scale))x.png")
            writePNG(ctx.makeImage()!, to: url)
            print("paint: \(url.path.dropFirst(root.path.count + 1))")
        }
    }
}

// MARK: - Main

let arguments = CommandLine.arguments.dropFirst()
let root = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
for argument in arguments where !["--proof", "--store"].contains(argument) {
    fail("unknown argument \(argument); see scripts/paint/README.md")
}
writeAssets(root: root)
if arguments.contains("--store") { writeStore(root: root) }
if arguments.contains("--proof") { writeProofs(root: root) }
